(function() {
  if (document.getElementById('tw-lang-filter-container')) return;

  var header = document.querySelector('.ibRGZe');
  if (!header) return;

  var container = document.createElement('div');
  container.id = 'tw-lang-filter-container';
  container.style.cssText = 'display:flex;align-items:center;gap:10px;margin-bottom:16px;padding:10px 16px;background:#1a1a2a;border-radius:8px;border:1px solid #3a3a4a;';

  var label = document.createElement('span');
  label.textContent = '🌐 Filter by language:';
  label.style.cssText = 'color:#bf94ff;font-weight:700;font-size:14px;white-space:nowrap;';

  var select = document.createElement('select');
  select.id = 'tw-lang-filter-select';
  select.style.cssText = 'padding:8px 12px;border-radius:6px;border:1px solid #535353;background:#0e0e10;color:#efeff1;font-size:14px;font-weight:600;cursor:pointer;outline:none;min-width:160px;';

  var allOption = document.createElement('option');
  allOption.value = 'all';
  allOption.textContent = 'All languages';
  select.appendChild(allOption);

  var langMap = {};
  var tags = document.querySelectorAll('.iKmojN .tw-tag[data-a-target]');
  var knownLangs = ['English', 'Spanish', 'Portuguese', 'French', 'German', 'Japanese', 'Korean', 'Chinese', 'Russian', 'Turkish', 'Italian', 'Polish', 'Arabic', 'Hindi', 'Dutch', 'Swedish', 'Norwegian', 'Danish', 'Finnish', 'Czech', 'Hungarian', 'Romanian', 'Greek', 'Thai', 'Vietnamese', 'Indonesian', 'Tagalog', 'Hebrew', 'Ukrainian', 'Bengali'];

  tags.forEach(function(tag) {
    var lang = tag.getAttribute('data-a-target');
    if (lang && !langMap[lang]) {
      langMap[lang] = true;
    }
  });

  knownLangs.forEach(function(lang) {
    if (langMap[lang]) {
      var opt = document.createElement('option');
      opt.value = lang;
      opt.textContent = lang;
      select.appendChild(opt);
      delete langMap[lang];
    }
  });

  Object.keys(langMap).forEach(function(lang) {
    var opt = document.createElement('option');
    opt.value = lang;
    opt.textContent = lang;
    select.appendChild(opt);
  });

  container.appendChild(label);
  container.appendChild(select);
  header.parentNode.insertBefore(container, header.nextSibling);

  select.addEventListener('change', function() {
    var selected = select.value;
    var cards = document.querySelectorAll('.iKmojN');
    cards.forEach(function(card) {
      if (selected === 'all') {
        card.style.display = '';
        return;
      }
      var langTag = card.querySelector('.tw-tag[data-a-target="' + selected + '"]');
      card.style.display = langTag ? '' : 'none';
    });
  });
})();

